    Mappings current = getCurrentMappings(tableName);
    if (current == null) {
        // If there's no current mapping, return an empty Mappings instance
        return new Mappings();
    }

    // Extract the properties section from both the current and historical mappings
    java.util.Map<String, Object> currentProps =
            (java.util.Map<String, Object>) current.toMap().get("properties");
    java.util.Map<String, Object> historyProps =
            (java.util.Map<String, Object>) mappings.toMap().get("properties");

    // Prepare a map to hold the diff of new fields
    java.util.Map<String, Object> diffProps = new java.util.HashMap<>();

    // Iterate over the historical properties and keep only those that do not exist
    // in the current mapping, while skipping the "_source" config
    for (String field : historyProps.keySet()) {
        if (!"_source".equals(field) && !currentProps.containsKey(field)) {
            diffProps.put(field, historyProps.get(field));
        }
    }

    // Construct the resulting diff mapping
    java.util.Map<String, Object> diffMap = new java.util.HashMap<>();
    diffMap.put("properties", diffProps);

    return new Mappings(diffMap);
}

