public static String findAndSubst(String key, Properties props) {
    // Retrieve the property value for the specified key
    String value = props.getProperty(key);
    if (value == null) {
        // If the key is not found, return null
        return null;
    }

    // Pattern to match ${...} placeholders
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer result = new StringBuffer();

    while (matcher.find()) {
        // Extract the variable name inside the placeholder
        String varName = matcher.group(1);
        // Look up the variable's value in the properties
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            varValue = "";
        }
        // Replace the placeholder with the actual value
        matcher.appendReplacement(result, java.util.regex.Matcher.quoteReplacement(varValue));
    }
    matcher.appendTail(result);
    return result.toString();
}

