private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Handle nulls: if both are null, return true; if str is null and suffix not null, return false
    if (str == null) {
        return suffix == null;
    }
    // If suffix is null, consider it as a match (empty suffix)
    if (suffix == null) {
        return true;
    }

    if (ignoreCase) {
        int slen = suffix.length();
        int len = str.length();
        if (slen > len) {
            return false;
        }
        // Compare the end part of str with suffix in a case-insensitive manner
        String end = str.substring(len - slen);
        return end.equalsIgnoreCase(suffix);
    } else {
        return str.endsWith(suffix);
    }
}

