    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = 0;
    if (path.charAt(0) == '/') {
        start = 1;
    }
    for (int i = start; i < path.length(); ) {
        int slash = path.indexOf('/', i);
        String seg;
        if (slash == -1) {
            seg = path.substring(i);
            i = path.length();
        } else {
            seg = path.substring(i, slash);
            i = slash + 1;
        }
        if (seg.isEmpty()) {
            continue;
        }
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // If UTF-8 not supported, keep the original segment
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

