public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint along the X axis
    double midX = (box.getMinX() + box.getMaxX()) / 2.0;

    // Create the left (or lower) box spanning from minX to midX
    Box2D leftBox = new Box2D(
        box.getMinX(),
        midX,
        box.getMinY(),
        box.getMaxY()
    );

    // Create the right (or upper) box spanning from midX to maxX
    Box2D rightBox = new Box2D(
        midX,
        box.getMaxX(),
        box.getMinY(),
        box.getMaxY()
    );

    // Return the pair of resulting boxes
    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size){
    // Ensure the internal byte array can hold the current size plus the requested additional space.
    int required = this.size + size;          // 'size' is the current number of bytes used
    if (required <= buffer.length) {
        return; // No need to enlarge
    }
    // Compute a new capacity, at least double the current or the required size, whichever is larger.
    int newCapacity = Math.max(buffer.length << 1, required);
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuffer, 0, this.size);
    buffer = newBuffer;
}

