public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    StringBuilder sb = new StringBuilder();
    sb.append(sdf.format(new java.util.Date(event.getTimeStamp()))).append(' ');
    sb.append(event.getLevel()).append(' ');
    sb.append(event.getLoggerName()).append(" - ");
    Object messageObj = event.getMessage();
    if (messageObj != null) {
        if (messageObj instanceof Object[]) {
            Object[] params = (Object[]) messageObj;
            if (params.length > 0 && params[0] instanceof String) {
                String pattern = (String) params[0];
                Object[] args = java.util.Arrays.copyOfRange(params, 1, params.length);
                try {
                    sb.append(java.lang.String.format(pattern, args));
                } catch (Exception e) {
                    sb.append(pattern);
                    sb.append(" [").append(java.util.Arrays.toString(args)).append(']');
                }
            } else {
                sb.append(java.util.Arrays.toString(params));
            }
        } else {
            sb.append(messageObj.toString());
        }
    }
    if (event.getThrowableInformation() != null) {
        sb.append(System.lineSeparator());
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        event.getThrowableInformation().getThrowable().printStackTrace(pw);
        pw.flush();
        sb.append(sw.toString());
    }
    return sb.toString();
}

