private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the start node itself is the stop node, return immediately.
    if (circ.getNode().equals(stop)) {
        return circ;
    }
    // Traverse along the outer face in the specified direction until we either
    // encounter a node that satisfies the predicate or we reach the stop node.
    while (!circ.getNode().equals(stop) && !predicate.test(circ.getNode())) {
        circ.next();
    }
    return circ;
}

