public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate inputs
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be >= 0");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new ArrayIndexOutOfBoundsException("byteOffset/byteLength out of bounds");
        }
    }

    // Ensure the internal buffer has enough space
    int newSize = this.byteLength + byteLength;
    if (newSize > this.byteArray.length) {
        int newCapacity = Math.max(this.byteArray.length * 2, newSize);
        byte[] newArray = new byte[newCapacity];
        System.arraycopy(this.byteArray, 0, newArray, 0, this.byteLength);
        this.byteArray = newArray;
    }

    // Copy the bytes (or fill with zeroes if source is null)
    if (byteArrayValue == null) {
        java.util.Arrays.fill(this.byteArray, this.byteLength, this.byteLength + byteLength, (byte) 0);
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.byteArray, this.byteLength, byteLength);
    }

    this.byteLength = newSize;
    return this;
}

