public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> ranges = new ArrayList<>();
    if (profiles == null) {
        return ranges;
    }
    for (Profile profile : profiles) {
        // Obtain the current segment of the profile
        Segment currentSegment = profile.getCurrentSegment();
        if (currentSegment == null) continue;

        // Grab the snapshot attached to this segment
        Snapshot snapshot = currentSegment.getSnapshot();
        if (snapshot == null) continue;

        // Extract the search sequence ranges from the snapshot
        Collection<SequenceRange> seqRanges = snapshot.getSearchSequenceRanges();
        if (seqRanges != null) {
            ranges.addAll(seqRanges);
        }
    }
    // Remove duplicates while preserving order
    Set<SequenceRange> unique = new LinkedHashSet<>(ranges);
    ranges.clear();
    ranges.addAll(unique);

    // Optional: sort the ranges by their start value if the class provides a getter
    ranges.sort(Comparator.comparingInt(sr -> sr.getStart()));

    return ranges;
}

