private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Quick checks
    if (list == null || list.first == null) {
        return;
    }

    // Acquire locks on both lists in a fixed order to avoid deadlock
    Object firstLock = this;
    Object secondLock = list;
    if (System.identityHashCode(firstLock) > System.identityHashCode(secondLock)) {
        Object tmp = firstLock;
        firstLock = secondLock;
        secondLock = tmp;
    }

    synchronized (firstLock) {
        synchronized (secondLock) {
            // Attach list's nodes to the end of this list
            if (this.first == null) {
                // This list is empty
                this.first = list.first;
                this.last = list.last;
            } else {
                // Link the two lists
                this.last.next = list.first;
                list.first.prev = this.last;
                this.last = list.last;
            }
            // Update sizes
            this.size += list.size;

            // Clear the source list
            list.first = null;
            list.last = null;
            list.size = 0;
        }
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If either is null (but not both), no match
    if (str == null || prefix == null) {
        return false;
    }
    // If we should ignore case, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        if (prefix.length() > str.length()) {
            return false;
        }
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

