public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (count <= 0) {
        return true;
    }
    if (a == null || b == null) {
        return false;
    }
    if (a.length < count || b.length < count) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if(typeVariable == null){
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if(bounds == null || bounds.length == 0){
        return Unknown.class;
    }
    Type bound = bounds[0];
    if(bound instanceof Class && bound == Object.class){
        return Unknown.class;
    }
    return bound;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() < 2) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort(sorted);
    for (K key : keys) {
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            idx = -idx - 1;
        }
        if (idx == 0) {
            lowerBounds.add(-1); // no lower bound found
        } else {
            lowerBounds.add(idx - 1); // index of maximum lower bound in sorted list
        }
    }
    return lowerBounds;
}

