static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int len = array.length;
    int count = 0;
    for (int i = 0; i < len; i++) {
        if (array[i] != null) {
            count++;
        }
    }
    if (count == len) {
        return (String[]) array;
    }
    String[] result = new String[count];
    int idx = 0;
    for (int i = 0; i < len; i++) {
        if (array[i] != null) {
            result[idx++] = (String) array[i];
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastUnixSep = filename.lastIndexOf('/');
    int lastWindowsSep = filename.lastIndexOf('\\');
    int lastSep = Math.max(lastUnixSep, lastWindowsSep);
    if (lastSep > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    long currentTime = System.currentTimeMillis();
    return (currentTime - timestamp) > expiredThreshold;
}

Edge edgeToNext(){
    // Obtain the node that will be returned on the next call
    Node next = nodeIterator.next();
    if (next == null) {
        previousNode = null;
        return null;
    }

    // If this is the first call, there is no previous node to connect from
    if (previousNode == null) {
        previousNode = next;
        return null;
    }

    // Resolve virtual nodes to their real counterparts, if applicable
    Node src = previousNode.isVirtual() ? previousNode.getRealNode() : previousNode;
    Node tgt = next.isVirtual() ? next.getRealNode() : next;

    // Create the edge between the resolved nodes
    Edge edge = new Edge(src, tgt);

    // Prepare for the next call
    previousNode = next;

    return edge;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str==null || substring==null) return false;
    int strLen = str.length();
    int subLen = substring.length();
    if(index < 0 || index + subLen > strLen) return false;
    for(int i=0;i<subLen;i++){
        if(str.charAt(index + i) != substring.charAt(i)){
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event){
    String message = event.getFormattedMessage();
    // Assume `clients` is a thread‑safe collection holding all connected sockets
    synchronized (clients) {
        // Iterate over a copy to safely modify the original collection
        for (Socket client : new java.util.ArrayList<>(clients)) {
            try {
                java.io.PrintWriter out = new java.io.PrintWriter(
                        client.getOutputStream(), true);
                out.println(message);
            } catch (java.io.IOException e) {
                // Remove the faulty client and close its socket
                clients.remove(client);
                try {
                    client.close();
                } catch (java.io.IOException ignore) {
                }
            }
        }
    }
}

