private void checkIfPackedField() throws IOException {
    // A packed field is encoded using the length-delimited wire type (type=2).
    // If the current field uses this wire type, set the internal flag to
    // indicate that packed fields are now being read.
    if (this.wireType == WIRETYPE_LENGTH_DELIMITED) {
        this.packedField = true;
    }
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // Reached EOF; no more tags.
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint tag");
}

