public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    // Regular expression to extract timestamp value from JSON snippet
    Pattern tsPattern = Pattern.compile("\"timestamp\"\\s*:\\s*(\\d+)");
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip empty lines
            if (line.trim().isEmpty()) {
                continue;
            }
            // Attempt to find a timestamp in the line
            Matcher m = tsPattern.matcher(line);
            if (!m.find()) {
                // If no timestamp is found, skip this line (or you could log a warning)
                continue;
            }
            long timestamp = Long.parseLong(m.group(1));
            // Filter by supplied time ranges
            if (timeRanges != null && !timeRanges.isEmpty()) {
                boolean inside = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    // Assume ProfileAnalyzeTimeRange exposes getStart() and getEnd() returning long
                    if (timestamp >= range.getStart() && timestamp <= range.getEnd()) {
                        inside = true;
                        break;
                    }
                }
                if (!inside) {
                    continue; // timestamp not within any requested range
                }
            }
            // Create a ThreadSnapshot instance from the raw line (or adjust according to actual constructor)
            snapshots.add(new ThreadSnapshot(timestamp, line));
        }
    }
    return snapshots;
}
